endpoint.request:
category_ids: int[]   (required, min 1, ogni id esistente in product_categories)
parent_id:    int|null (required ma nullable; null = sposta alla radice;
                        se valorizzato deve esistere in product_categories)

endpoint.response:
{ success: true, message: "Categories moved", data: { moved: int } }
`moved` = numero di categorie il cui parent_id e' stato effettivamente scritto
(una categoria gia' figlia del target e' un no-op e NON viene contata).
